from functools import lru_cache
@lru_cache(None)
def full(n):  # all full binary tree shapes (each node has 0 or 2 children); shape = (left, right)
    if n == 1: return ((None, None),)
    return tuple((l, r) for k in range(1, n - 1, 2) for l in full(k) for r in full(n - 1 - k))
@lru_cache(None)
def anyb(n):  # all binary tree shapes with n nodes
    if n == 0: return (None,)
    return tuple((l, r) for k in range(n) for l in anyb(k) for r in anyb(n - 1 - k))
def lab(t, order, c):  # label nodes so that traversal `order` reads 0,1,2,...
    if t is None: return None
    if order == 'pre': me = next(c); L = lab(t[0], order, c); R = lab(t[1], order, c)
    elif order == 'in': L = lab(t[0], order, c); me = next(c); R = lab(t[1], order, c)
    else: L = lab(t[0], order, c); R = lab(t[1], order, c); me = next(c)
    return (me, L, R)
def trav(t, o):
    if t is None: return ()
    m, l, r = t
    return {'pre': (m,) + trav(l, o) + trav(r, o), 'in': trav(l, o) + (m,) + trav(r, o),
            'post': trav(l, o) + trav(r, o) + (m,)}[o]
def unique(shapes, fixed, other):
    # WLOG relabel so the `fixed` traversal is 0..n-1; the pair then identifies the tree
    # iff no two shapes give the same `other` traversal (other=None: fixed traversal alone)
    keys = [trav(lab(s, fixed, iter(range(99))), other) if other else () for s in shapes]
    return len(set(keys)) == len(keys)
for n in range(1, 16, 2):
    sh = full(n)
    assert unique(sh, 'in', 'pre') and unique(sh, 'in', 'post') and unique(sh, 'pre', 'post')
    assert unique(sh, 'in', None) == (n < 5)
    print(n, len(sh), 'A pre+in', unique(sh, 'in', 'pre'), 'B in+post', unique(sh, 'in', 'post'),
          'C pre+post', unique(sh, 'pre', 'post'), 'D in only', unique(sh, 'in', None))
print('general binary trees, n=2, pre+post unique?', unique(anyb(2), 'pre', 'post'))
for s in full(5):  # the two full trees whose inorder is 1..5
    t = lab(s, 'in', iter(range(99)))
    print('inorder', [v + 1 for v in trav(t, 'in')], 'preorder', [v + 1 for v in trav(t, 'pre')])
